import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Was brauche ich, bevor ich den Adapter installiere?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/01.voraussetzungen.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","filePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","lastUpdated":1795571670000}'),i={name:"de/adapter/esphome/erste-schritte/voraussetzungen.md"};function n(d,e,h,o,u,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="was-brauche-ich-bevor-ich-den-adapter-installiere" tabindex="-1">Was brauche ich, bevor ich den Adapter installiere? <a class="header-anchor" href="#was-brauche-ich-bevor-ich-den-adapter-installiere" aria-label="Permalink to &quot;Was brauche ich, bevor ich den Adapter installiere?&quot;">​</a></h1><p><a id="have-install-python-pip-myself"></a></p><h2 id="muss-ich-python-oder-pip-selbst-installieren" tabindex="-1">Muss ich Python oder pip selbst installieren? <a class="header-anchor" href="#muss-ich-python-oder-pip-selbst-installieren" aria-label="Permalink to &quot;Muss ich Python oder pip selbst installieren?&quot;">​</a></h2><p>Nein. Für die Geräte braucht der Adapter kein Python. Nur das integrierte Dashboard braucht Python, und dafür legt der Adapter eine eigene Umgebung an und installiert ESPHome hinein. Ein Python oder pip auf deinem System nutzt er nicht.</p><p>Du brauchst nur Node.js 22.12 oder neuer. Beim ersten Start des Dashboards lädt der Adapter Python und die Pakete aus dem Internet, das dauert einige Minuten. Welche Python-Version er nimmt, steht unter „Fortschrittlich“ im Feld „Python-Version“, Standard ist 3.13.2.</p><p><strong>Siehe auch:</strong> <a href="#systems-hardware-adapter-run">Auf welchen Systemen läuft der Adapter?</a> · <a href="./../fehlerbehebung/dashboard-startet-nicht#clear-autopy-cache-if-python">Python-Umgebung zurücksetzen</a></p><p><a id="systems-hardware-adapter-run"></a></p><h2 id="auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" tabindex="-1">Auf welchen Systemen und mit welcher Hardware läuft der Adapter? <a class="header-anchor" href="#auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" aria-label="Permalink to &quot;Auf welchen Systemen und mit welcher Hardware läuft der Adapter?&quot;">​</a></h2><p>Der Adapter läuft auf jedem System mit ioBroker und Node.js 22.12 oder neuer. Das integrierte ESPHome-Dashboard läuft nur auf 64-Bit-Linux und macOS.</p><table tabindex="0"><thead><tr><th>Was</th><th>Voraussetzung</th></tr></thead><tbody><tr><td>Adapter mit Geräten</td><td>Node.js 22.12 oder neuer, Admin 7.8.20 oder neuer, js-controller 6.0.11 oder neuer</td></tr><tr><td>Integriertes Dashboard</td><td>zusätzlich 64-Bit-Linux oder macOS und Internetzugang beim Start</td></tr><tr><td>Dashboard mit „Docker-Integration verwenden (Beta)“</td><td>zusätzlich Docker auf dem ioBroker-Rechner</td></tr></tbody></table><p>Für die Geräte braucht der Adapter kein Python, er spricht sie direkt über die Native API an. Python braucht nur das integrierte Dashboard. Der Adapter legt dafür beim Start eine eigene Umgebung an, standardmäßig mit Python 3.13.2.</p><p>Ein Raspberry Pi mit 64-Bit-Prozessor ist trotzdem ein 32-Bit-System, wenn das Betriebssystem in 32 Bit installiert ist. Dort startet das Dashboard erst nach einer Neuinstallation mit 64-Bit-Betriebssystem.</p><h3 id="welche-hardware-brauche-ich" tabindex="-1">Welche Hardware brauche ich? <a class="header-anchor" href="#welche-hardware-brauche-ich" aria-label="Permalink to &quot;Welche Hardware brauche ich?&quot;">​</a></h3><p>Für die Geräte reicht jede Hardware, auf der ioBroker läuft. Das Dashboard kompiliert Firmware, das braucht viel Rechenleistung und Arbeitsspeicher. Ein Raspberry Pi 3 wird dabei sehr langsam, ein Raspberry Pi 4 läuft stabil. Ist dein Rechner zu schwach oder läuft er unter Windows, betreibe das Dashboard auf einem anderen Rechner.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#use-external-esphome-dashboard-instead">Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten?</a></p><p><a id="need-home-assistant-mqtt-use"></a></p><h2 id="brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" tabindex="-1">Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen? <a class="header-anchor" href="#brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" aria-label="Permalink to &quot;Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen?&quot;">​</a></h2><p>Nein. Der Adapter verbindet sich direkt über die Native API von ESPHome mit dem Gerät. Home Assistant und MQTT brauchst du dafür nicht.</p><p>In der YAML des Geräts muss der Abschnitt <code>api:</code> stehen, am besten mit Verschlüsselungsschlüssel. Ohne <code>api:</code> erreicht der Adapter das Gerät nicht. Steht zusätzlich <code>mqtt:</code> in der YAML, stört das den Adapter nicht.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  encryption</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;Schlüssel des Geräts&gt;&quot;</span></span></code></pre></div><p><strong>Siehe auch:</strong> <a href="./erstes-geraet#add-esphome-device-adapter">Gerät im Adapter hinzufügen</a> · <a href="./../hintergrund/esphome-projekte#use-esphome-over-mqtt-instead">ESPHome über MQTT nutzen</a></p>`,21)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
